fts5.h1_f:
CREATE VIRTUAL TABLE meddelanden_fts USING fts5(
  innehåll, -- tokeniserad kolumn
  rums-id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
fråga: SELECT rowid FROM messages_fts WHERE innehåll MATCH 'foo'

